{
  "findings": [
    {
      "check_id": "CKV_AZURE_109",
      "title": "Linux Function App should have HTTPS Only enabled",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "HIGH",
      "explanation": "The resource does not explicitly set 'https_only = true', allowing traffic over HTTP which can lead to data interception or man-in-the-middle attacks."
    },
    {
      "check_id": "CKV_AZURE_110",
      "title": "Linux Function App should use Managed Identity instead of Storage Account Access Key",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "CRITICAL",
      "explanation": "Using 'storage_account_access_key' in the configuration exposes sensitive credentials in state files and logs. It is best practice to use System Assigned or User Assigned Managed Identities for authentication to Azure Storage."
    }
  ],
  "patched_code": "resource "azurerm_linux_function_app" "alert_function" {
  name                = "smart-manufacturing-iot-monitoring-platform-function-app-alerts"
  resource_group_name = azurerm_resource_group.smart_manufacturing.name
  location            = azurerm_resource_group.smart_manufacturing.location
  service_plan_id     = azurerm_service_plan.dashboard_plan.id
  storage_account_name       = azurerm_storage_account.function_storage.name
  # Removed storage_account_access_key to prevent secret exposure
  https_only          = true
  identity {
    type         = "SystemAssigned"
  }
  site_config {
    application_stack {
      node_version = "18"
    }
  }
  app_settings = {
    "FUNCTIONS_WORKER_RUNTIME" = "node"
    # Note: When using Managed Identity, ensure the Function App's principal has 
    # appropriate RBAC roles (e.g., Storage Blob Data Owner) on the storage account.
    # The WEBSITE_CONTENTAZUREFILECONNECTIONSTRING might need adjustment depending 
    # on specific runtime requirements, but removing the key from TF code is the primary fix.
  }
}",
  "fix_summary": "Enabled HTTPS-only traffic by setting 'https_only = true'. Replaced the hardcoded 'storage_account_access_key' with a System Assigned Managed Identity ('identity { type = "SystemAssigned" }') to avoid storing secrets in Terraform state and improve security posture."
}
